<?php
function migrate_enquiries(): void {
 $version='20261026_sheet_enquiry_inbox_v1';if(db_value('SELECT COUNT(*) FROM app_migrations WHERE version=?',[$version]))return;
 $lock='enquiries_'.substr(hash('sha256',(string)db_value('SELECT DATABASE()')),0,20);if(!db_value('SELECT GET_LOCK(?,30)',[$lock]))throw new ApiError('Enquiry update in progress.',503);
 try{if(db_value('SELECT COUNT(*) FROM app_migrations WHERE version=?',[$version]))return;
 db()->exec("CREATE TABLE IF NOT EXISTS enquiry_integration(id INT PRIMARY KEY,spreadsheet_id VARCHAR(150) NOT NULL,tab_name VARCHAR(150) NOT NULL,token_hash CHAR(64) NULL,is_enabled TINYINT NOT NULL DEFAULT 0,last_received_at DATETIME NULL,last_success_at DATETIME NULL,full_sync_requested TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 db()->exec("INSERT IGNORE INTO enquiry_integration(id,spreadsheet_id,tab_name) VALUES(1,'1TGNVd26CRgXpXE3K7BFZjnA1MCc6cAdtY71ZdokCje8','Form Responses 1')");
 db()->exec("CREATE TABLE IF NOT EXISTS enquiries(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id VARCHAR(150) NOT NULL UNIQUE,source_data LONGTEXT NOT NULL,source_hash CHAR(64) NOT NULL,name VARCHAR(150) NULL,mobile VARCHAR(20) NULL,email VARCHAR(150) NULL,city VARCHAR(100) NULL,source_name VARCHAR(100) NOT NULL,enquiry_at DATETIME NULL,assigned_to INT UNSIGNED NULL,contact_id INT UNSIGNED NULL,lead_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY enquiry_mobile(mobile),KEY enquiry_email(email),FOREIGN KEY(assigned_to) REFERENCES users(id),FOREIGN KEY(contact_id) REFERENCES contacts(id),FOREIGN KEY(lead_id) REFERENCES leads(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 db()->exec("CREATE TABLE IF NOT EXISTS enquiry_sync_runs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_key VARCHAR(80) NOT NULL UNIQUE,received_at DATETIME NOT NULL,added INT NOT NULL DEFAULT 0,updated INT NOT NULL DEFAULT 0,unchanged INT NOT NULL DEFAULT 0,errors_json LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 if(!db_value("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='followups' AND COLUMN_NAME='enquiry_id'"))db()->exec('ALTER TABLE followups ADD enquiry_id INT UNSIGNED NULL, ADD enquiry_decision VARCHAR(30) NULL, ADD KEY idx_followup_enquiry(enquiry_id,activity_at,id), ADD CONSTRAINT fk_followup_enquiry FOREIGN KEY(enquiry_id) REFERENCES enquiries(id)');
 if(db_value("SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='followups' AND CONSTRAINT_NAME='chk_followup_target'"))db()->exec('ALTER TABLE followups DROP '.(stripos((string)db_value('SELECT VERSION()'),'MariaDB')!==false?'CONSTRAINT':'CHECK').' chk_followup_target');
 if(!db_value("SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='followups' AND CONSTRAINT_NAME='chk_followup_target_enquiry'"))db()->exec('ALTER TABLE followups ADD CONSTRAINT chk_followup_target_enquiry CHECK (((contact_id IS NOT NULL)+(lead_id IS NOT NULL)<=1) AND (contact_id IS NOT NULL OR lead_id IS NOT NULL OR enquiry_id IS NOT NULL))');
 db()->exec("CREATE OR REPLACE VIEW crm_enquiry_current AS SELECT e.*,u.name AS assigned_name,f.enquiry_decision,f.next_followup_at,f.remarks AS last_remarks,f.activity_at AS last_followup_at,(SELECT COUNT(*) FROM followups h WHERE h.enquiry_id=e.id) AS followup_count,CASE WHEN e.lead_id IS NOT NULL THEN 'Lead Created' WHEN e.contact_id IS NOT NULL THEN 'Contact Added' WHEN f.enquiry_decision='Archive' THEN 'Archived' WHEN f.id IS NULL THEN 'New' ELSE 'Follow up Later' END COLLATE utf8mb4_unicode_ci AS inbox_status FROM enquiries e LEFT JOIN users u ON u.id=e.assigned_to LEFT JOIN followups f ON f.id=(SELECT x.id FROM followups x WHERE x.enquiry_id=e.id ORDER BY x.activity_at DESC,x.id DESC LIMIT 1)");
 db()->prepare('INSERT INTO app_migrations(version,applied_at) VALUES(?,?)')->execute([$version,now()]);
 }finally{db_value('SELECT RELEASE_LOCK(?)',[$lock]);}
}

// 27-Oct-2026: Meta lead ads now arrive in "ladecore leads 2026" → Sheet1. Enquiries already imported are kept
// (they are identified by the Meta lead id, not the sheet). The old key is cleared: download a new script.
function migrate_enquiry_sheet(): void {
 $version='20261027_enquiry_sheet_ladecore_leads';if(db_value('SELECT COUNT(*) FROM app_migrations WHERE version=?',[$version]))return;
 db()->prepare("UPDATE enquiry_integration SET spreadsheet_id=?,tab_name=?,token_hash=NULL,is_enabled=0,full_sync_requested=0 WHERE id=1")->execute(['1XN3UEDu3y2I669-j2KsHB9vdlVKviq6nNWUo-hUnKE8','Sheet1']);
 db()->prepare('INSERT IGNORE INTO app_migrations(version,applied_at) VALUES(?,?)')->execute([$version,now()]);
}
